// Guess the Algorithm: 一個檔案即可上傳 GitHub 部署 Render
// Node.js 20+; 除此之外沒有任何外部相依套件
import { createServer } from 'node:http';
import { randomBytes, randomUUID, createHash } from 'node:crypto';
import { EventEmitter } from 'node:events';


const ASSETS = {"socket-shim.js": "", "index.html": "", "app.js": "", "style.css": ""};

// 零外部依賴、僅供小型派對 MVP 使用的 WebSocket 事件通道。
// 生產環境大量流量請改用受維護的 WebSocket 套件及專業限流。

function serverFrame(payload, opcode = 1) {
  const input = opcode === 1 ? Buffer.from(JSON.stringify(payload)) : Buffer.from(payload);
  const header = input.length < 126 ? Buffer.from([0x80 | opcode,input.length])
    : input.length <= 65535 ? Buffer.from([0x80 | opcode,126,input.length>>8,input.length&255])
    : Buffer.from([0x80 | opcode,127,0,0,0,0,(input.length/0x1000000)&255,(input.length>>16)&255,(input.length>>8)&255,input.length&255]);
  return Buffer.concat([header,input]);
}

function createRealtime(server) {
  const sockets = new Map();
  const io = new EventEmitter();
  io.to = socketId => ({emit(event, data) { sockets.get(socketId)?.send(event,data); }});
  server.on('upgrade',(req,raw,head)=>{
    if (new URL(req.url,'http://localhost').pathname !== '/realtime') return raw.destroy();
    const key = req.headers['sec-websocket-key'];
    if (req.headers.upgrade?.toLowerCase() !== 'websocket' || typeof key !== 'string') return raw.destroy();
    const accept = createHash('sha1').update(key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
    raw.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+accept+'\r\n\r\n');
    const events = new EventEmitter();
    const socket = {
      id: randomUUID(),data:{},
      on:(event,fn)=>{events.on(event,fn);return socket;},
      emit:(event,data)=>{socket.send(event,data);},
      send(event,data){if(!raw.destroyed)raw.write(serverFrame({event,data}));},
      join:()=>{},leave:()=>{},
    };
    sockets.set(socket.id,socket);
    let pending = Buffer.alloc(0), ended=false;
    const disconnect=()=>{if(ended)return;ended=true;sockets.delete(socket.id);events.emit('disconnect');};
    const handle=(chunk)=>{
      if(ended)return;
      pending = Buffer.concat([pending,chunk]);
      if(pending.length > 200_000) {raw.destroy();return;}
      while(pending.length>=2){
        const b0=pending[0], b1=pending[1];
        const opcode=b0&15,fin=!!(b0&0x80),masked=!!(b1&0x80);
        let len=b1&127,offset=2;
        if(len===126){if(pending.length<4)return;len=pending.readUInt16BE(2);offset=4;}
        else if(len===127){if(pending.length<10)return;const big=pending.readBigUInt64BE(2);if(big>100_000n){raw.destroy();return;}len=Number(big);offset=10;}
        if(len>100_000||!masked||(!fin && opcode!==0x9)){raw.destroy();return;}
        if(pending.length<offset+4+len)return;
        const key=pending.subarray(offset,offset+4);
        const bytes=Buffer.from(pending.subarray(offset+4,offset+4+len));
        pending=pending.subarray(offset+4+len);
        for(let i=0;i<bytes.length;i++)bytes[i]^=key[i%4];
        if(opcode===0x8){raw.end(serverFrame(Buffer.alloc(0),8));disconnect();return;}
        if(opcode===0x9){raw.write(serverFrame(bytes,10));continue;}
        if(opcode!==0x1)continue;
        try {
          const msg=JSON.parse(bytes.toString('utf8'));
          if(typeof msg.event!=='string'||msg.event.length>64)continue;
          const cb=(response)=>{if(typeof msg.ackId==='string')socket.send('__ack',{id:msg.ackId,response});};
          events.emit(msg.event,msg.data,cb);
        } catch {}
      }
    };
    raw.on('data',handle); raw.on('close',disconnect);raw.on('error',disconnect);
    io.emit('connection',socket);
    if(head?.length)handle(head);
  });
  return io;
}


const FILES = {
  '/':'index.html', '/index.html':'index.html', '/style.css':'style.css',
  '/app.js':'app.js','/socket-shim.js':'socket-shim.js',
};
const MIME = {html:'text/html; charset=utf-8',css:'text/css; charset=utf-8',js:'text/javascript; charset=utf-8'};
const httpServer=createServer(async(req,res)=>{
  const path = new URL(req.url,'http://localhost').pathname;
  if(path==='/health'){
    res.setHeader('Content-Type','application/json');
    res.end(JSON.stringify({ok:true,youtubeAvailable:!!process.env.YOUTUBE_API_KEY}));return;
  }
  const name=FILES[path];
  if(req.method!=='GET'||!name){res.statusCode=404;res.end('Not found');return;}
  try {
    const data=Buffer.from(ASSETS[name], 'base64');
    res.setHeader('Content-Type',MIME[name.split('.').at(-1)]||'text/plain');
    res.setHeader('X-Content-Type-Options','nosniff');
    res.end(data);
  }catch{res.statusCode=500;res.end('Internal error');}
});
const io = createRealtime(httpServer);

