const rooms = new Map();
const cache = new Map();
const MAX_PLAYERS = 12;
const config = { youtubeAvailable: !!process.env.YOUTUBE_API_KEY, maxPlayers: MAX_PLAYERS };

function makeCode() {
  let code;
  do { code = randomBytes(4).toString('hex').slice(0, 6).toUpperCase(); } while (rooms.has(code));
  return code;
}
function cleanName(v) { return typeof v === 'string' ? v.trim().replace(/[<>\x00-\x1f]/g, '').slice(0, 18) : ''; }
function ok(cb, data = {}) { if (typeof cb === 'function') cb({ ok: true, ...data }); }
function fail(cb, error) { if (typeof cb === 'function') cb({ ok: false, error }); }
function findRoom(socket, cb, requireHost = false) {
  const info = socket.data.player;
  const room = info && rooms.get(info.roomCode);
  const player = room && room.players.find(p => p.id === info.id);
  if (!room || !player) { fail(cb, '尚未加入房間'); return null; }
  if (requireHost && room.hostId !== player.id) { fail(cb, '只有房主能操作'); return null; }
  return { room, player };
}
function publicState(room, viewerId) {
  const round = room.rounds[room.index];
  const state = {
    code: room.code, hostId: room.hostId, selfId: viewerId, phase: room.phase,
    index: room.index, total: room.rounds.length,
    players: room.players.map(p => ({ id: p.id, name: p.name, bot: p.bot, ready: p.topics.length >= 3, connected: p.connected, score: p.score, voted: !!round?.votes?.[p.id] })),
    videoSource: room.videoSource, error: room.error || '', trainingSeconds: room.trainingSeconds || 60, trainingEndsAt: room.trainingEndsAt || 0, trainingFinished: room.players.filter(p=>p.bot || p.trained).length,
  };
  if(room.phase==='training') { const p=room.players.find(x=>x.id===viewerId); state.trainingVideo=p?.trainingQueue?.[p.trainingIndex||0] || null; state.trainingIndex=p?.trainingIndex||0; state.trainingCount=p?.trainingQueue?.length||0; state.trained=!!p?.trained; }
  if (round && ['guess','reveal','done'].includes(room.phase)) {
    const v = round.video;
    state.video = { id: v.id, source: v.source, title: v.title, emoji: v.emoji, description: v.description, colors: v.colors, embedUrl: v.embedUrl, watchUrl: v.watchUrl, thumbnail: v.thumbnail };
    if (room.phase !== 'guess') {
      state.result = { recommended: round.recommended, scores: round.scores, votes: round.votes, gains: round.gains };
    }
  }
  return state;
}
function publish(room) {
  for (const p of room.players) {
    if (p.socketId) io.to(p.socketId).emit('room:state', publicState(room, p.id));
  }
}
function touch(room) { room.updatedAt = Date.now(); }
function calcRound(video, players) {
  const scores = {};
  for (const p of players) {
    const matching = video.tags.filter(t => p.topics.includes(t)).length;
    // 小幅、可重現的擾動，只是為了讓模擬推薦不完全同分。
    const noise = [...`${video.id}:${p.id}`].reduce((n, c) => (n * 33 + c.charCodeAt(0)) % 997, 13) / 997;
    const learned = video.tags.reduce((sum,t)=>sum+(p.learned?.[t]||0),0);
    scores[p.id] = Math.round((matching * 3 + learned + noise) * 10) / 10;
  }
  const sorted = [...players].sort((a,b) => scores[b.id] - scores[a.id]);
  const highest = scores[sorted[0].id];
  let rec = sorted.filter(p => scores[p.id] >= 3.0 && scores[p.id] >= highest * 0.68).slice(0, 3).map(p => p.id);
  if (!rec.length) rec = [sorted[0].id];
  return { video, recommended: rec, scores, votes: {}, gains: {} };
}
function shuffle(a) {
  const out = [...a];
  for (let i = out.length - 1; i > 0; i--) {
    const j = randomBytes(2).readUInt16BE() % (i + 1);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
function reveal(room) {
  if (room.phase !== 'guess') return;
  const round = room.rounds[room.index];
  const correct = new Set(round.recommended);
  for (const p of room.players) {
    if (p.bot) continue;
    const vote = new Set(round.votes[p.id] || []);
    const intersection = [...vote].filter(id => correct.has(id)).length;
    const union = new Set([...vote, ...correct]).size;
    const gain = vote.size ? Math.round(100 * intersection / Math.max(1, union)) : 0;
    p.score += gain;
    round.gains[p.id] = gain;
  }
  room.phase = 'reveal';
  touch(room);
  publish(room);
}
function next(room) {
  if (room.phase !== 'reveal') return;
  if (room.index + 1 >= room.rounds.length) room.phase = 'done';
  else { room.index++; room.phase = 'guess'; }
  touch(room); publish(room);
}
async function findYoutubeVideos(topics, desired) {
  if (!process.env.YOUTUBE_API_KEY) throw new Error('伺服器尚未設定 YOUTUBE_API_KEY');
  const picked = shuffle(topics).slice(0, 6);
  const found = [];
  const calls = picked.map(async tag => {
    const cacheKey = `yt:${tag}`;
    const hit = cache.get(cacheKey);
    if (hit && Date.now() - hit.time < 12 * 60 * 1000) return hit.videos;
    const q = new URLSearchParams({
      part: 'snippet', type: 'video', videoDuration: 'short', videoEmbeddable: 'true',
      safeSearch: 'strict', maxResults: '15', q: TOPICS[tag].query,
      regionCode: 'TW', relevanceLanguage: 'zh-Hant', order: 'relevance',
      key: process.env.YOUTUBE_API_KEY,
    });
    const response = await fetch(`https://www.googleapis.com/youtube/v3/search?${q}`);
    const body = await response.json();
    if (!response.ok) throw new Error(`YouTube API 搜尋失敗：${body.error?.message || response.status}`);
    const videos = (body.items || []).filter(x => x.id?.videoId).map(x => ({
      id: `yt-${x.id.videoId}`, source: 'youtube', title: x.snippet.title,
      description: x.snippet.channelTitle, tags: [tag],
      thumbnail: x.snippet.thumbnails?.high?.url || x.snippet.thumbnails?.medium?.url,
      embedUrl: `https://www.youtube-nocookie.com/embed/${x.id.videoId}?playsinline=1&rel=0`,
      watchUrl: `https://www.youtube.com/watch?v=${x.id.videoId}`,
    }));
    cache.set(cacheKey, { time: Date.now(), videos });
    return videos;
  });
  const results = await Promise.allSettled(calls);
  for (const result of results) if (result.status === 'fulfilled') found.push(...result.value);
  if (!found.length) throw new Error('找不到可播放的短影片。請確認 API 金鑰與配額。');
  const unique = [...new Map(found.map(v => [v.id, v])).values()];
  // 按文字關鍵字擴充影片類型標籤；不是影片內容理解模型。
  const searchWords = {
    funny: /funny|comedy|meme|笑|搞笑/i, animals:/cat|dog|pet|animal|貓|狗/i,
    kpop:/kpop|k-pop|idol|韓團|아이돌/i, beauty:/makeup|beauty|outfit|妝|穿搭/i,
    gaming:/game|gaming|roblox|minecraft|遊戲/i, food:/food|cook|recipe|美食|料理/i,
    travel:/travel|trip|景點|旅遊/i, fitness:/gym|fitness|sport|運動/i,
    music:/music|dance|song|cover|跳舞|音樂/i, science:/science|tech|facts|科學|科技/i,
    weird:/weird|oddly|satisfying|奇怪|神奇/i, romance:/couple|love|dating|戀愛|情侶/i,
  };
  for (const v of unique) for (const [t, regex] of Object.entries(searchWords)) if (regex.test(v.title)) v.tags = [...new Set([...v.tags, t])];
  return shuffle(unique).slice(0, desired);
}


function finishTraining(room){
 if(room.phase!=='training')return;
 const pool=room.candidates||[];
 const selected=pool.slice(0,Math.min(room.requestedCount||8,pool.length));
 room.rounds=selected.map(v=>calcRound(v,room.players));
 room.phase='guess';room.index=0;touch(room);publish(room);
}

io.on('connection', socket => {
  socket.emit('server:config', config);
  socket.on('room:create', (data, cb) => {
    if (rooms.size >= 300) return fail(cb, '目前房間數量已滿');
    const name = cleanName(data?.name);
    if (!name) return fail(cb, '請輸入暱稱');
    const code = makeCode(), id = randomUUID();
    const p = { id, name, topics: [], bot: false, score: 0, socketId: socket.id, connected: true };
    const room = { code, hostId: id, phase: 'lobby', players: [p], rounds: [], index: 0, error: '', videoSource: 'demo', updatedAt: Date.now() };
    rooms.set(code, room);
    socket.data.player = { roomCode: code, id };
    socket.join(code);
    ok(cb, { code, playerId: id }); publish(room);
  });
  socket.on('room:join', (data, cb) => {
    const code = String(data?.code || '').trim().toUpperCase();
    const room = rooms.get(code);
    if (!room) return fail(cb, '找不到房間，請確認房號');
    const possibleId = typeof data?.playerId === 'string' ? data.playerId : '';
    let p = room.players.find(x => x.id === possibleId && !x.bot);
    if (!p) {
      if (room.phase !== 'lobby') return fail(cb, '遊戲已開始，暫時不能加入新玩家');
      if (room.players.length >= MAX_PLAYERS) return fail(cb, '房間已滿');
      const name = cleanName(data?.name);
      if (!name) return fail(cb, '請輸入暱稱');
      if (room.players.some(x => x.name.toLowerCase() === name.toLowerCase())) return fail(cb, '暱稱已有人使用');
      p = { id: randomUUID(), name, topics: [], bot: false, score: 0, socketId: null, connected: true };
      room.players.push(p);
    }
    if (p.socketId && p.socketId !== socket.id) io.to(p.socketId).emit('session:replaced');
    p.socketId = socket.id; p.connected = true;
    socket.data.player = { roomCode: code, id: p.id };
    socket.join(code); touch(room); ok(cb, { code, playerId: p.id }); publish(room);
  });
  socket.on('player:topics', (data, cb) => {
    const found = findRoom(socket, cb); if (!found) return;
    const {room, player} = found;
    if (room.phase !== 'lobby') return fail(cb, '遊戲開始後不能修改興趣');
    const topics = [...new Set(Array.isArray(data?.topics) ? data.topics : [])].filter(t => TOPICS[t]);
    if (topics.length < 3 || topics.length > 5) return fail(cb, '請選擇 3 至 5 個興趣');
    player.topics = topics; touch(room); ok(cb); publish(room);
  });
  socket.on('room:addBots', (_, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    if (f.room.phase !== 'lobby') return fail(cb, '只能在大廳加入示範玩家');
    if (f.room.players.some(p => p.bot)) return fail(cb, '已經有示範玩家了');
    const bots = [
      { name: '迷因王', topics: ['funny', 'gaming', 'weird', 'science'] },
      { name: '貓咪控', topics: ['animals', 'food', 'travel', 'funny'] },
      { name: '追星人', topics: ['kpop', 'music', 'beauty', 'romance'] },
    ];
    for (const bot of bots) f.room.players.push({ ...bot, id: randomUUID(), bot: true, score: 0, connected: true, socketId: null });
    touch(f.room); ok(cb); publish(f.room);
  });
  socket.on('room:removeBots', (_, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    if (f.room.phase !== 'lobby') return fail(cb, '只能在大廳移除示範玩家');
    f.room.players = f.room.players.filter(p => !p.bot);
    touch(f.room); ok(cb); publish(f.room);
  });
  socket.on('room:start', async (data, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    const room = f.room;
    if (room.phase !== 'lobby') return fail(cb, '遊戲已開始');
    if (!room.players.every(p => p.topics.length >= 3)) return fail(cb, '請等所有人完成興趣設定');
    if (room.players.length < 2) return fail(cb, '至少需要 2 位玩家；獨自測試可加入示範玩家');
    const source = data?.source === 'youtube' ? 'youtube' : 'demo';
    if (source === 'youtube' && !config.youtubeAvailable) return fail(cb, '尚未設定影片搜尋金鑰');
    const count = [5,8,10].includes(Number(data?.count)) ? Number(data.count) : 8;
    room.phase = 'loading'; room.error = ''; room.videoSource = source; room.requestedCount=count; room.trainingSeconds = 60; touch(room); publish(room);
    try {
      const tags = [...new Set(room.players.flatMap(p => p.topics))];
      const candidates = source === 'youtube' ? await findYoutubeVideos(tags, count * 3) : shuffle(DEMO_VIDEOS);
      const selected = candidates.slice(0, Math.min(count, candidates.length));
      if (selected.length < 3) throw new Error('可使用的影片不足 3 支，請改用示範題卡');
      room.candidates = candidates;
      room.index = 0; room.players.forEach(p => {p.score=0;p.learned={};p.trained=false;p.trainingIndex=0;p.lastSignal=0;});
      if(source==='youtube') {
        room.phase='training';room.trainingEndsAt=Date.now()+60000;
        for(const p of room.players){p.trainingQueue=shuffle(candidates).slice(0,Math.min(12,candidates.length));if(p.bot)p.trained=true;}
        const code=room.code, ends=room.trainingEndsAt;
        setTimeout(()=>{const r=rooms.get(code);if(r?.phase==='training'&&r.trainingEndsAt===ends) finishTraining(r);},61000).unref();
      } else { room.rounds=selected.map(v=>calcRound(v,room.players));room.phase='guess'; }
      touch(room); ok(cb, { rounds: selected.length }); publish(room);
    } catch (err) {
      room.phase = 'lobby'; room.error = String(err.message || err).slice(0, 180);
      touch(room); fail(cb, room.error); publish(room);
    }
  });
  socket.on('training:signal',(data,cb)=>{
    const f=findRoom(socket,cb);if(!f)return;
    const {room,player}=f;
    if(room.phase!=='training'||player.bot||player.trained)return fail(cb,'目前無法記錄');
    const now=Date.now();if(now>room.trainingEndsAt+1500)return fail(cb,'觀看時間已結束');
    if(now-(player.lastSignal||0)<350)return fail(cb,'操作太快');
    const video=player.trainingQueue?.[player.trainingIndex||0];
    if(!video)return fail(cb,'影片已看完');
    if(data?.videoId!==video.id)return fail(cb,'影片不一致');
    const kind=data?.kind;
    if(!['watch','like','skip','replay'].includes(kind))return fail(cb,'不支援的行為');
    const elapsed=Math.max(0,Math.min(30,Number(data?.seconds)||0));
    const delta=kind==='like'?3:kind==='replay'?2:kind==='skip'?-1:Math.min(2,elapsed/8);
    player.learned ||= {};
    for(const tag of video.tags)player.learned[tag]=Math.max(-4,Math.min(15,(player.learned[tag]||0)+delta));
    player.lastSignal=now;
    if(kind==='skip'||kind==='replay'){player.trainingIndex=(player.trainingIndex+1)%(player.trainingQueue.length||1);}
    touch(room);ok(cb);publish(room);
  });
  socket.on('training:finish',(_,cb)=>{
    const f=findRoom(socket,cb);if(!f)return;
    if(f.room.phase!=='training')return fail(cb,'觀看已結束');
    if(Date.now()<f.room.trainingEndsAt)return fail(cb,'倒數尚未結束');
    f.player.trained=true;ok(cb);finishTraining(f.room);
  });
  socket.on('round:vote', (data, cb) => {
    const f = findRoom(socket, cb); if (!f) return;
    const {room,player} = f;
    if (player.bot) return fail(cb, '示範玩家不能作答');
    if (room.phase !== 'guess') return fail(cb, '現在不是作答時間');
    const round = room.rounds[room.index];
    if (round.votes[player.id]) return fail(cb, '這題已經提交過答案');
    const vote = [...new Set(Array.isArray(data?.ids) ? data.ids : [])];
    const allowed = new Set(room.players.map(p=>p.id));
    if (!vote.length || vote.length > 3 || vote.some(id => !allowed.has(id))) return fail(cb, '請選 1 至 3 位玩家');
    round.votes[player.id] = vote;
    touch(room); ok(cb); publish(room);
    if (room.players.filter(p => !p.bot && p.connected).every(p => !!round.votes[p.id])) reveal(room);
  });
  socket.on('round:reveal', (_, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    if (f.room.phase !== 'guess') return fail(cb, '目前不能揭曉');
    reveal(f.room); ok(cb);
  });
  socket.on('round:next', (_, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    if (f.room.phase !== 'reveal') return fail(cb, '請先揭曉答案');
    next(f.room); ok(cb);
  });
  socket.on('room:reset', (_, cb) => {
    const f = findRoom(socket, cb, true); if (!f) return;
    const r = f.room;
    r.phase='lobby'; r.rounds=[]; r.index=0; r.error=''; r.candidates=[]; r.players.forEach(p => p.score=0);
    touch(r); ok(cb); publish(r);
  });
  socket.on('room:leave', (_, cb) => {
    const f = findRoom(socket, cb); if (!f) return;
    const r = f.room;
    r.players = r.players.filter(p => p.id !== f.player.id);
    socket.leave(r.code); socket.data.player = undefined;
    if (!r.players.length || r.players.every(p => p.bot)) rooms.delete(r.code);
    else {
      if (r.hostId === f.player.id) r.hostId = (r.players.find(p => !p.bot) || r.players[0]).id;
      if (r.phase === 'guess' && r.players.filter(p => !p.bot && p.connected).every(p => !!r.rounds[r.index]?.votes?.[p.id])) reveal(r);
      touch(r); publish(r);
    }
    ok(cb);
  });
  socket.on('disconnect', () => {
    const info = socket.data.player;
    const room = info && rooms.get(info.roomCode);
    const p = room?.players.find(p=>p.id===info.id);
    if (p && p.socketId===socket.id) {
      p.connected=false; p.socketId=null;
      if (room.phase === 'guess' && room.players.filter(x=>!x.bot && x.connected).every(x=>!!room.rounds[room.index]?.votes?.[x.id])) reveal(room);
      touch(room); publish(room);
    }
  });
});

const timer = setInterval(() => {
  const now = Date.now();
  for (const [code, room] of rooms) if (now - room.updatedAt > 4 * 60 * 60 * 1000) rooms.delete(code);
}, 60_000);
timer.unref();

if (process.env.NODE_ENV !== 'test') {
  const port = process.env.PORT || 3000;
  httpServer.listen(port, '0.0.0.0', () => console.log(`Guess the Algorithm → http://localhost:${port}`));
}
export { io, httpServer, calcRound, DEMO_VIDEOS };
